// Fail closed unless exactly one unsent, unapproved August 2026 DRAFT is being recovered.
const rows = $input.all().map((item) => item.json ?? {}).filter((row) => Object.keys(row).length > 0);
if (rows.length !== 1) throw new Error('Recovery denied: expected exactly one DRAFT row');
const row = rows[0];
const clean = (value) => String(value ?? '').trim();
const reportMonth = clean(row.reportMonth);
const reportType = clean(row.reportType).toUpperCase();
const state = clean(row.documentStatus).toUpperCase();
const fileName = clean(row.pdfFileName);
const oldFileId = clean(row.pdfDriveFileId);
const oldUrl = clean(row.pdfDriveUrl);
const approvedAt = clean(row.approvedAt);
const sentAt = clean(row.sentAt);
const reportBody = clean(row.reportBody);
if (reportMonth !== '2026-08' || reportType !== 'MONTHLY_MAINTENANCE' || state !== 'DRAFT' || approvedAt || sentAt) throw new Error('Recovery denied: report is not the expected unsent DRAFT');
if (fileName !== 'Cavetta-Monthly-Maintenance-Report-2026-08.pdf') throw new Error('Recovery denied: unexpected PDF filename');
const objectKey = `Cavetta Maintenance Reports/2026/${fileName}`;
const r2Url = `r2://cavetta-private-storage/${objectKey}`;
const isLegacyDrive = /^[A-Za-z0-9_-]{10,200}$/.test(oldFileId) && /^https:\/\/drive\.google\.com\//i.test(oldUrl);
const isExactPriorRecovery = oldFileId === objectKey && oldUrl === r2Url;
if (!isLegacyDrive && !isExactPriorRecovery) throw new Error('Recovery denied: unexpected existing PDF storage metadata');
if (reportBody.length < 20) throw new Error('Recovery denied: stored report body is unavailable');
return [{ json: { ...row, reportMonth, reportType, fileName, objectKey } }];

const source = $json;

// Recovery is deliberately self-contained; retain the original template defaults.
const maintenanceConfig = {};

const clientName = String(
  maintenanceConfig.client_name ?? "Cavetta Properties"
).trim();

const publicSiteUrl = String(
  maintenanceConfig.public_site_url ?? "https://cavetta.mt/"
).trim();

const companyLogoUrl = String(
  maintenanceConfig.company_logo_url ??
    "https://ik.imagekit.io/4z66kkrjv/company-assets/cloudit_logo.png"
).trim();

const reportSenderName = String(
  maintenanceConfig.report_sender_name ?? "CloudIT Pvt Ltd"
).trim();

const escapeHtml = (value) =>
  String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");

const text = (value, fallback = "") => {
  const result = String(value ?? "").trim();
  return result || fallback;
};

const normalizedStatus = (value) =>
  text(value, "NO_DATA").toUpperCase();

const numeric = (value) => {
  if (value === null || value === undefined || value === "") {
    return null;
  }

  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
};

const displayNumber = (
  value,
  status = "GREEN",
  suffix = "",
  maximumFractionDigits = 2
) => {
  if (normalizedStatus(status) === "NO_DATA") {
    return "N/A";
  }

  const parsed = numeric(value);

  if (parsed === null) {
    return "N/A";
  }

  return (
    parsed.toLocaleString("en-GB", { maximumFractionDigits }) +
    suffix
  );
};

const formatBytes = (value, status = "GREEN") => {
  if (normalizedStatus(status) === "NO_DATA") {
    return "N/A";
  }

  const bytes = numeric(value);

  if (bytes === null || bytes < 0) {
    return "N/A";
  }

  if (bytes === 0) {
    return "0 B";
  }

  const units = ["B", "KB", "MB", "GB", "TB"];
  const unitIndex = Math.min(
    Math.floor(Math.log(bytes) / Math.log(1000)),
    units.length - 1
  );

  return `${(bytes / Math.pow(1000, unitIndex)).toFixed(2)} ${units[unitIndex]}`;
};

const statusClass = (value) => {
  const status = normalizedStatus(value);

  if (["GREEN", "FULL", "HEALTHY", "SUCCESS", "AVAILABLE", "OK", "PASS"].includes(status)) {
    return "status-good";
  }

  if (["RED", "FAILED", "FAILURE", "CRITICAL", "FAIL"].includes(status)) {
    return "status-bad";
  }

  return "status-warning";
};

const statusBadge = (value) => {
  const status = normalizedStatus(value);

  return `<span class="status ${statusClass(status)}">${escapeHtml(
    status.replaceAll("_", " ")
  )}</span>`;
};

const safeLink = (url, label) => {
  const value = text(url);

  if (!/^https:\/\/[^\s]+$/i.test(value)) {
    return `<span class="muted">Not available</span>`;
  }

  return `<a href="${escapeHtml(value)}">${escapeHtml(label)}</a>`;
};

const parseJsonArray = (value) => {
  try {
    const parsed = JSON.parse(String(value ?? "[]"));
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
};

const expectedSources = [
  ["WEEKLY_HEALTH", "Weekly health and availability"],
  ["INCIDENTS_RECOVERIES", "Incidents and recoveries"],
  ["BACKUP_RESTORE", "Backup and isolated restore-test evidence"],
  ["GA4_ANALYTICS", "GA4"],
  ["VERCEL_WEB_ANALYTICS", "Vercel Web Analytics"],
  ["SUPABASE_INFRASTRUCTURE", "Supabase infrastructure"],
  ["IMAGEKIT_USAGE", "ImageKit usage"],
];

const parsedSnapshots = parseJsonArray(source.sourceSnapshotsJson);
const snapshotsByKey = new Map(
  parsedSnapshots.map((snapshot) => [text(snapshot.sourceKey), snapshot])
);

const reportMonth = text(source.reportMonth, "unknown").replace(/[^0-9-]/g, "");
const reportMonthLabel = text(source.reportMonthLabel, reportMonth);

const snapshots = expectedSources.map(([sourceKey, sourceLabel]) => {
  const stored = snapshotsByKey.get(sourceKey);

  if (stored) {
    return {
      ...stored,
      sourceKey,
      sourceLabel: text(stored.sourceLabel, sourceLabel),
      coverage: normalizedStatus(stored.coverage),
    };
  }

  return {
    sourceKey,
    sourceLabel,
    reportMonth,
    coverage: "NO_DATA",
    freshness: "UNKNOWN",
    validationStatus: "MISSING",
    requestedPeriodStart: "",
    requestedPeriodEndExclusive: "",
    requestedTimezone: "Europe/Malta",
    providerTimezone: "",
    boundarySemantics: "",
    actualPeriodStart: "",
    actualPeriodEndExclusive: "",
    capturedAt: "",
    sourceAsOf: "",
    evidenceCount: 0,
    expectedEvidenceCount: null,
    retentionLimit: "",
    latestSafeCollectionAt: "",
    coverageDetail: `No stored ${reportMonth} snapshot exists for this required source.`,
    actionRequired: "Keep the report in DRAFT and investigate the missing scheduled snapshot.",
  };
});

const getSnapshot = (sourceKey) =>
  snapshots.find((snapshot) => snapshot.sourceKey === sourceKey);

const loadedSnapshotCount = snapshots.filter(
  (snapshot) => text(snapshot.validationStatus).toUpperCase() === "PRESENT"
).length;

const partialSnapshotCount = snapshots.filter(
  (snapshot) => snapshot.coverage === "PARTIAL"
).length;

const noDataSnapshotCount = snapshots.filter(
  (snapshot) => snapshot.coverage === "NO_DATA"
).length;

const invalidSnapshotCount = snapshots.filter((snapshot) =>
  ["MISSING", "DUPLICATE", "INVALID_COVERAGE"].includes(
    text(snapshot.validationStatus).toUpperCase()
  )
).length;

const snapshotContractComplete =
  parsedSnapshots.length === expectedSources.length &&
  loadedSnapshotCount === expectedSources.length &&
  invalidSnapshotCount === 0;

const snapshotContractStatus = snapshotContractComplete ? "PASS" : "FAIL";

const snapshotOverallCoverage =
  noDataSnapshotCount > 0
    ? "NO_DATA"
    : partialSnapshotCount > 0
      ? "PARTIAL"
      : "FULL";

const firstSnapshot = snapshots[0] ?? {};
const canonicalRequestedStart = text(firstSnapshot.requestedPeriodStart, "Not available");
const canonicalRequestedEnd = text(
  firstSnapshot.requestedPeriodEndExclusive,
  "Not available"
);
const canonicalTimezone = text(firstSnapshot.requestedTimezone, "Europe/Malta");

const evidenceCards = snapshots
  .map((snapshot) => {
    const expectedEvidence = numeric(snapshot.expectedEvidenceCount);
    const evidenceText = `${numeric(snapshot.evidenceCount) ?? 0} of ${
      expectedEvidence === null ? "not specified" : expectedEvidence
    }`;

    return `
      <article class="evidence-card">
        <div class="card-row">
          <h3>${escapeHtml(snapshot.sourceLabel)}</h3>
          ${statusBadge(snapshot.coverage)}
        </div>

        <dl class="evidence-details">
          <dt>Requested period</dt>
          <dd>${escapeHtml(text(snapshot.requestedPeriodStart, "Not available"))} to ${escapeHtml(
            text(snapshot.requestedPeriodEndExclusive, "Not available")
          )} exclusive (${escapeHtml(text(snapshot.requestedTimezone, "Not documented"))})</dd>

          <dt>Actual period</dt>
          <dd>${escapeHtml(text(snapshot.actualPeriodStart, "Not available"))} to ${escapeHtml(
            text(snapshot.actualPeriodEndExclusive, "Not available")
          )} exclusive</dd>

          <dt>Capture / source-as-of</dt>
          <dd>${escapeHtml(text(snapshot.capturedAt, "Not available"))} / ${escapeHtml(
            text(snapshot.sourceAsOf, "Not available")
          )}</dd>

          <dt>Freshness / evidence</dt>
          <dd>${escapeHtml(text(snapshot.freshness, "UNKNOWN"))} / ${escapeHtml(evidenceText)}</dd>

          <dt>Provider boundaries</dt>
          <dd>${escapeHtml(text(snapshot.providerTimezone, "Not documented"))}; ${escapeHtml(
            text(snapshot.boundarySemantics, "Not documented")
          )}</dd>

          <dt>Retention</dt>
          <dd>${escapeHtml(text(snapshot.retentionLimit, "Not documented"))}</dd>
        </dl>

        <p><strong>Coverage:</strong> ${escapeHtml(
          text(snapshot.coverageDetail, "No coverage detail available")
        )}</p>

        ${
          snapshot.coverage !== "FULL"
            ? `<div class="source-warning"><strong>Action:</strong> ${escapeHtml(
                text(snapshot.actionRequired, "Review this source before approval.")
              )}</div>`
            : ""
        }
      </article>
    `;
  })
  .join("");

const overallResult = normalizedStatus(source.overallResult);
const healthResult = normalizedStatus(source.healthResult);
const incidentResult = normalizedStatus(source.incidentResult);
const backupResult = normalizedStatus(source.backupResult);
const analyticsResult = normalizedStatus(source.analyticsResult);
const vercelAnalyticsResult = normalizedStatus(source.vercelAnalyticsResult);
const supabaseInfrastructureResult = normalizedStatus(
  source.supabaseInfrastructureResult
);
const supabaseApiRequestResult = normalizedStatus(source.supabaseApiRequestResult);
const imagekitUsageResult = normalizedStatus(source.imagekitUsageResult);
const imagekitQuotaStatus = normalizedStatus(source.imagekitQuotaStatus);

const expectedOverviewServices = [
  "Uptime Kuma",
  "Vercel",
  "Supabase",
  "ImageKit",
  "Backups",
];

const parsedInfrastructureOverview = parseJsonArray(
  source.infrastructureOverviewJson
);

const overviewByService = new Map(
  parsedInfrastructureOverview
    .filter(
      (entry) =>
        entry &&
        typeof entry === "object" &&
        !Array.isArray(entry)
    )
    .map((entry) => [text(entry.service), entry])
);

const infrastructureOverview = expectedOverviewServices.map(
  (service) => {
    const stored = overviewByService.get(service);

    if (stored) {
      return {
        service,
        healthStatus: normalizedStatus(stored.healthStatus),
        health: text(
          stored.health,
          "No service-health detail is available."
        ),
        analyticsStatus: normalizedStatus(
          stored.analyticsStatus
        ),
        usageAnalytics: text(
          stored.usageAnalytics,
          "No aggregate usage or analytics detail is available."
        ),
        evidenceLinks:
          stored.evidenceLinks &&
          typeof stored.evidenceLinks === "object" &&
          !Array.isArray(stored.evidenceLinks)
            ? stored.evidenceLinks
            : {},
      };
    }

    return {
      service,
      healthStatus: "NO_DATA",
      health: "No service-health detail is available.",
      analyticsStatus: "NO_DATA",
      usageAnalytics:
        "No aggregate usage or analytics detail is available. This does not indicate application downtime.",
      evidenceLinks: {},
    };
  }
);

const infrastructureOverviewRows = infrastructureOverview
  .map((entry) => {
    const backupUrl = text(
      entry.evidenceLinks.latestBackupRun
    );
    const restoreUrl = text(
      entry.evidenceLinks.latestRestoreTestRun
    );

    const evidenceLinks = [
      backupUrl
        ? safeLink(backupUrl, "Latest backup run")
        : "",
      restoreUrl
        ? safeLink(restoreUrl, "Latest restore-test run")
        : "",
    ]
      .filter(Boolean)
      .join(" &middot; ");

    return `
      <tr>
        <td><strong>${escapeHtml(entry.service)}</strong></td>
        <td>
          ${statusBadge(entry.healthStatus)}
          <p class="overview-detail">${escapeHtml(entry.health)}</p>
        </td>
        <td>
          ${statusBadge(entry.analyticsStatus)}
          <p class="overview-detail">${escapeHtml(entry.usageAnalytics)}</p>
          ${evidenceLinks ? `<p class="overview-links">${evidenceLinks}</p>` : ""}
        </td>
      </tr>
    `;
  })
  .join("");

const vercelSnapshot = getSnapshot("VERCEL_WEB_ANALYTICS");
const supabaseSnapshot = getSnapshot("SUPABASE_INFRASTRUCTURE");
const imagekitSnapshot = getSnapshot("IMAGEKIT_USAGE");

const vercelTopRoutes = parseJsonArray(source.vercelTopRoutesJson).slice(0, 5);
const vercelRouteRows =
  vercelAnalyticsResult !== "NO_DATA" && vercelTopRoutes.length > 0
    ? vercelTopRoutes
        .map(
          (route, index) => `
            <tr>
              <td>${index + 1}</td>
              <td>${escapeHtml(route.path ?? "/")}</td>
              <td>${displayNumber(route.visitors, vercelAnalyticsResult, "", 0)}</td>
              <td>${displayNumber(route.pageviews, vercelAnalyticsResult, "", 0)}</td>
            </tr>
          `
        )
        .join("")
    : `<tr><td colspan="4" class="muted">No public route data available for this exact report period.</td></tr>`;

const generatedAt = new Intl.DateTimeFormat("en-GB", {
  dateStyle: "long",
  timeStyle: "short",
  timeZone: "Europe/Malta",
}).format(new Date());

const executiveSummary = text(
  source.executiveSummary,
  "This DRAFT requires review before approval."
);

const actionRequired = text(
  source.actionRequired ?? source.recommendedAction ?? source.recommendedActions,
  overallResult === "GREEN"
    ? "Continue routine monitoring."
    : "Review the sections marked AMBER, RED, PARTIAL, or NO_DATA."
);

const supabaseActionRequired = text(
  source.supabaseInfrastructureActionRequired,
  "None"
);

const imagekitActionRequired = text(source.imagekitUsageActionRequired, "None");
const pdfFileName = `Cavetta-Monthly-Maintenance-Report-${reportMonth}.pdf`;

const metricCard = (value, label) => `
  <div class="metric">
    <span class="metric-value">${escapeHtml(value)}</span>
    <span class="metric-label">${escapeHtml(label)}</span>
  </div>
`;

const html = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <style>
    @page { size: A4; margin: 14mm; }
    * { box-sizing: border-box; }
    body { margin: 0; color: #171717; background: #fff; font-family: Arial, Helvetica, sans-serif; font-size: 10.5pt; line-height: 1.45; }
    .page { width: 100%; }
    .header { display: flex; align-items: center; justify-content: space-between; gap: 24px; padding-bottom: 16px; border-bottom: 2px solid #202020; }
    .logo { display: block; width: 145px; height: auto; object-fit: contain; }
    .company { text-align: right; font-size: 9pt; color: #4b4b4b; }
    .company strong { display: block; color: #171717; font-size: 11pt; margin-bottom: 3px; }
    h1 { margin: 24px 0 4px; font-size: 23pt; line-height: 1.2; }
    h2 { margin: 24px 0 10px; font-size: 15pt; page-break-after: avoid; }
    h3 { margin: 0 0 8px; font-size: 11pt; }
    p { margin: 0 0 8px; }
    .subtitle { margin: 0; color: #5b5b5b; font-size: 11pt; }
    .summary { margin-top: 20px; padding: 18px; border: 1px solid #d6d6d6; border-radius: 8px; background: #f7f7f7; page-break-inside: avoid; }
    .summary-heading, .card-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
    .summary-heading { margin-bottom: 10px; }
    .summary-heading h2 { margin: 0; font-size: 14pt; }
    .status { display: inline-block; min-width: 76px; padding: 5px 10px; border: 1px solid; border-radius: 999px; text-align: center; font-size: 8.5pt; font-weight: 700; letter-spacing: .4px; }
    .status-good { color: #195c34; border-color: #85b899; background: #edf7f1; }
    .status-warning { color: #714f00; border-color: #d4b766; background: #fff8df; }
    .status-bad { color: #851f1f; border-color: #cf8d8d; background: #fff0f0; }
    .grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 12px; }
