    .evidence-card { margin-bottom: 10px; }
    .evidence-details { display: grid; grid-template-columns: 135px 1fr; gap: 4px 10px; margin: 8px 0; font-size: 8.5pt; }
    .evidence-details dt { color: #666; font-weight: 700; }
    .evidence-details dd { margin: 0; overflow-wrap: anywhere; }
    .source-warning { margin-top: 8px; padding: 9px; border-left: 4px solid #d4b766; background: #fff8df; }
    .metric-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
    .metric-grid-two { display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px; }
    .metric { padding: 13px 8px; text-align: center; border: 1px solid #ddd; border-radius: 7px; page-break-inside: avoid; }
    .metric-value { display: block; font-size: 20pt; line-height: 1.1; font-weight: 700; }
    .metric-label { display: block; margin-top: 5px; color: #666; font-size: 8.5pt; }
    table { width: 100%; border-collapse: collapse; }
    th, td { padding: 9px; border-bottom: 1px solid #ddd; text-align: left; vertical-align: top; }
    th { color: #555; font-weight: 600; }
    .overview-table { table-layout: fixed; }
    .overview-table th:first-child { width: 18%; }
    .overview-table th:nth-child(2) { width: 36%; }
    .overview-table th:nth-child(3) { width: 46%; }
    .overview-table tr { page-break-inside: avoid; }
    .overview-detail { margin: 7px 0 0; color: #555; font-size: 9pt; }
    .overview-links { margin: 7px 0 0; font-size: 8.5pt; }
    a { color: #222; text-decoration: underline; word-break: break-all; }
    .muted { color: #777; }
    .period { margin: 12px 0; padding: 10px; background: #f7f7f7; border-radius: 6px; color: #555; font-size: 9pt; overflow-wrap: anywhere; page-break-inside: avoid; }
    .action-box { padding: 14px; border-left: 4px solid #555; background: #f5f5f5; page-break-inside: avoid; }
    .section-spacing { margin-top: 12px; }
    .footer { margin-top: 28px; padding-top: 12px; border-top: 1px solid #d6d6d6; color: #6b6b6b; font-size: 8.5pt; text-align: center; }
  </style>
</head>
<body>
  <main class="page">
    <header class="header">
      <img class="logo" src="${escapeHtml(companyLogoUrl)}" alt="${escapeHtml(reportSenderName)}">
      <div class="company">
        <strong>${escapeHtml(reportSenderName)}</strong>
        <div>info@cloudit.lk</div>
        <div>www.cloudit.lk</div>
        <div>+94 75 686 8854</div>
      </div>
    </header>

    <h1>Monthly Maintenance Report</h1>
    <p class="subtitle">${safeLink(publicSiteUrl, clientName)} &mdash; ${escapeHtml(reportMonthLabel)}</p>

    <section class="summary">
      <div class="summary-heading"><h2>Executive summary</h2>${statusBadge(overallResult)}</div>
      <p>${escapeHtml(executiveSummary)}</p>
    </section>

    <h2>Monthly source-evidence assurance</h2>
    <section class="summary">
      <div class="summary-heading"><h2>Snapshot contract</h2>${statusBadge(snapshotContractStatus)}</div>
      <p><strong>Coverage:</strong> ${statusBadge(snapshotOverallCoverage)}</p>
      <p><strong>Snapshots loaded:</strong> ${loadedSnapshotCount} of ${expectedSources.length}</p>
      <p><strong>Requested calendar window:</strong> ${escapeHtml(canonicalRequestedStart)} to ${escapeHtml(canonicalRequestedEnd)} exclusive (${escapeHtml(canonicalTimezone)})</p>
      <p class="muted">Every PARTIAL or NO DATA source below must be reviewed before this DRAFT can be approved.</p>
    </section>

    <section class="section-spacing">${evidenceCards}</section>

    <h2>Consolidated infrastructure overview</h2>
    <p class="muted">Service health and aggregate usage evidence are shown separately. Missing analytics does not mean the live application was unavailable.</p>
    <table class="overview-table">
      <thead>
        <tr>
          <th>Service</th>
          <th>Health</th>
          <th>Usage / analytics</th>
        </tr>
      </thead>
      <tbody>${infrastructureOverviewRows}</tbody>
    </table>

    <h2>Google Analytics</h2>
    <section class="metric-grid">
      ${metricCard(displayNumber(source.totalUsers, analyticsResult, "", 0), "Total users")}
      ${metricCard(displayNumber(source.newUsers, analyticsResult, "", 0), "New users")}
      ${metricCard(displayNumber(source.sessions, analyticsResult, "", 0), "Sessions")}
      ${metricCard(displayNumber(source.screenPageViews, analyticsResult, "", 0), "Page views")}
    </section>
    <p class="muted section-spacing">${escapeHtml(text(getSnapshot("GA4_ANALYTICS").coverageDetail, "No GA4 coverage detail available."))}</p>

    <h2>Vercel Web Analytics</h2>
    <div class="summary-heading"><h3>Monthly traffic</h3>${statusBadge(vercelAnalyticsResult)}</div>
    <section class="metric-grid-two">
      ${metricCard(displayNumber(source.vercelVisitorCount, vercelAnalyticsResult, "", 0), "Visitors")}
      ${metricCard(displayNumber(source.vercelPageviewCount, vercelAnalyticsResult, "", 0), "Page views")}
    </section>
    <div class="period">Actual period: ${escapeHtml(text(source.vercelPeriodStart, "Not available"))} to ${escapeHtml(text(source.vercelPeriodEnd, "Not available"))} exclusive</div>
    <h3>Top five public routes</h3>
    <table><thead><tr><th>#</th><th>Public route</th><th>Visitors</th><th>Page views</th></tr></thead><tbody>${vercelRouteRows}</tbody></table>
    <p class="muted">${escapeHtml(text(vercelSnapshot.coverageDetail, "No Vercel coverage detail available."))}</p>

    <h2>Supabase infrastructure</h2>
    <div class="summary-heading"><h3>Monthly infrastructure health</h3>${statusBadge(supabaseInfrastructureResult)}</div>
    <p class="muted">${escapeHtml(text(supabaseSnapshot.coverageDetail, source.supabaseInfrastructureDetail ?? "No Supabase infrastructure details are available."))}</p>
    <section class="metric-grid">
      ${metricCard(displayNumber(source.supabaseInfrastructureSampleCount, supabaseInfrastructureResult, "", 0), "Reporting samples")}
      ${metricCard(displayNumber(source.supabaseDatabaseSizeStartMb, supabaseInfrastructureResult, " MB"), "Database size at start")}
      ${metricCard(displayNumber(source.supabaseDatabaseSizeEndMb, supabaseInfrastructureResult, " MB"), "Database size at end")}
      ${metricCard(displayNumber(source.supabaseDatabaseSizeGrowthMb, supabaseInfrastructureResult, " MB"), "Database growth")}
    </section>
    <div class="period">Sample period: ${escapeHtml(text(source.supabaseDatabaseSizeStartAt, "Not available"))} to ${escapeHtml(text(source.supabaseDatabaseSizeEndAt, "Not available"))} exclusive</div>
    <section class="metric-grid">
      ${metricCard(displayNumber(source.supabasePeakDirectConnections, supabaseInfrastructureResult, "", 0), "Peak direct connections")}
      ${metricCard(displayNumber(source.supabasePeakSupavisorConnections, supabaseInfrastructureResult, "", 0), "Peak Supavisor connections")}
      ${metricCard(displayNumber(source.supabasePeakConnectionUtilizationPercent, supabaseInfrastructureResult, "%"), "Peak PgBouncer utilization")}
      ${metricCard(displayNumber(source.supabasePeakDiskUsedPercent, supabaseInfrastructureResult, "%"), "Peak disk usage")}
    </section>
    <section class="metric-grid-two section-spacing">
      ${metricCard(displayNumber(source.supabasePeakMemoryUsedPercent, supabaseInfrastructureResult, "%"), "Peak memory usage")}
